fn reverse(s: Str) -> Str {
    let chars = chars(s)
    let len = len(chars)
    let mut result = ""
    for i in range(0, len) {
        let index = len - 1 - i
        result = concat(result, get(chars, index).unwrap_or(""))
    }
    result
}
