struct Item { name: Str, unit_price: Int, quantity: Int }
fn total_cost(items: Vec<Item>) -> Int {
    let mut sum = 0
    for item in items {
        sum += item.unit_price * item.quantity
    }
    sum
}
fn highest_cost_item(items: Vec<Item>) -> Option<Str> {
    let mut max_cost = -1
    let mut max_name = None
    for item in items {
        let cost = item.unit_price * item.quantity
        if cost > max_cost {
            max_cost = cost
            max_name = Some(item.name)
        }
    }
    max_name
}
fn main() {
    let items = vec(
        Item { name: "pen", unit_price: 3, quantity: 4 },
        Item { name: "pad", unit_price: 9, quantity: 2 },
        Item { name: "ink", unit_price: 5, quantity: 3 }
    )
    let total = total_cost(items)
    print(total)
    match highest_cost_item(vec(
        Item { name: "pen", unit_price: 3, quantity: 4 },
        Item { name: "pad", unit_price: 9, quantity: 2 },
        Item { name: "ink", unit_price: 5, quantity: 3 }
    )) {
        Some(name) => print_str(name),
        None => print_str("No items"),
    }
}
